  sideArticles: [],
  quote: "PARIGOT は、金沢の繁華街・片町に静かに灯る、パリの日常料理を楽しめる一軒。コース3種類とソムリエの提案、20席の落ち着いた空間で、大人のディナーをゆったり過ごせる。金沢でフランス料理を選びたくなったら、まさに、編集部イチオシのお店です。",
  quoteCite: "マチノワ編集部",
  closing: "金沢の街歩きの締めにフランス料理を据えるなら、午後から夜への流れをこう組みたい。15:00 金沢駅に到着し、まずは近江町市場やひがし茶屋街を散策（〜17:00）。17:30 兼六園・21世紀美術館エリアで夕景を楽しみ、18:30 香林坊を経由して片町へ。19:00、PARIGOT に到着。ディナーコース ¥5,000〜¥6,000 を軸に、ソムリエにワインの相談をしながら、ゆっくり2時間半ほどかけてパリの日常料理を味わう（〜21:30）。食後は犀川沿いを軽く散歩して、22時前に片町のホテルへ戻る流れがちょうどいい。記念日や誕生日なら、予約時にバースデープレートのリクエストを伝えておくと、夜の山場をひとつ確実に作れる。一人で訪れるなら、ランチ ¥2,000〜¥3,000 の時間帯にゆったり腰を据える使い方が向いている。月曜は夜のみ営業、日曜定休、月一回不定休があるので、訪問前に電話 076-254-1217 か Google マップで営業日を確認しておくと安心。テイクアウトにも対応するので、犀川沿いやホテルの部屋でフランス料理を楽しむ使い方も選択肢に入る。金沢に「パリの一日」を組み込みたいとき、PARIGOT はその一日にふさわしい締めになる。",
