  quote: "焼肉 遊は、武庫之荘という住宅街の街の夜に、家族でも、デートでも、接待でも頼れる一軒。完全個室と座敷キッズスペースを併せ持つ構造は、子育て世代が多いこの街の暮らしに自然と寄り添う。武庫之荘で焼肉と聞いたら、編集部としてまず思い出したい店です。",
