        desc: "ラーメンまるひら札幌店のもう一つの軸は、麺へのこだわりにある。札幌の老舗製麺所として知られる西山製麺と組み、9回の試作を経て仕上げた特注の細ちぢれ麺がそれだ。釧路ラーメンの伝統である細麺の食感を、札幌の麺事情のなかで再現するためのプロセスで、スープとの絡みや喉越しを細かく調整したと伝えられている。釧路本店の味の記憶を札幌の街で再構築するうえで、麺を地元の製麺所と作り直したという事実は大きい。観光客向けに釧路の名を借りた一軒ではなく、札幌で食べる釧路ラーメンを真面目に作り直そうとした店、という位置づけが見えてくる。澄んだスープと、細く縮れた麺。その組み合わせが一杯の核を成しており、道東の伝統と札幌の製麺技術が交わる、ここでしか味わえない一杯と言える。",
