    lede: "札幌市西区の西野二条は、地下鉄東西線・宮の沢駅から山側へ少し入った住宅街のエリアだ。手稲山方面へと続く山の手通り沿いに、戸建てとマンション、街の商店や飲食店が静かに並ぶ街並みで、観光客が押し寄せるエリアではなく、地元の人が日々を回している生活の街でもある。そんな西野二条の通りに、創業から40年以上にわたって暖簾を掲げてきた一軒が「寿司の松よし」だ。家族経営の寿司・和食店で、握り寿司を中心に、丼ものから鍋料理、2階の宴会座敷までを抱える、地域の食卓を支えてきた店である。札幌の中心街・すすきのの華やかな寿司店とはまた違う、住宅街の暮らしのなかにある「ちゃんとした寿司屋」という立ち位置で、地元の家族・常連・町内会の集まりまでを受け止めてきた。",
