        purpose: "クルマがなくても魚介食堂に通える人へ",
        desc: "北九州モノレール小倉線 徳力公団前駅から徒歩圏という立地は、この店の使い勝手を大きく押し上げている。小倉駅からモノレールに揺られて南へ20分弱、降りればそこは住宅街と商店が混在する徳力エリア。クルマがなくても電車一本でアクセスできる利便性は、北九州都市圏での魚介食堂として強みになる。徳力周辺は北九州市の中でも生活密着型のエリアで、団地・商店・公共施設が集まる落ち着いた街並みが広がる。地元の常連客と訪問客が無理なく混ざる空気があり、駐車場も用意されているため、クルマ移動の客にも開かれている。小倉エリアで魚を食べたい日、繁華街ではなく落ち着いて食事を取りたいなら、徳力公団前という選択肢は意外と筋がいい。駅からの導線も平坦で、徒歩での移動が苦にならない距離感だ。",
