        desc: "魚の光家は、昼11時から15時のランチタイムと、夕方17時から21時のディナータイムという二部構成で営業している。ランチタイムは海鮮丼や定食を中心とした構成で、徒歩客とクルマ客が入り混じる賑やかな時間帯。ディナータイムは少し落ち着いた時間の流れで、刺身や定食を肴に夕食を組み立てる使い方が想定される。日曜は昼のみの営業、水曜が定休となっているため、訪問前のスケジュール確認は必須だ。徳力周辺で平日ランチを探している会社員、休日に家族で出かけたい人、仕事帰りに魚で軽く食事を取りたい人――それぞれの時間帯に居場所がある営業設計になっている。とくに昼の海鮮丼は地元客に支持されており、ピーク時間帯（12時前後）を少しずらして訪れるのが、落ち着いて食事を取るコツになる。営業時間・定休日は時期や状況で変わる可能性があるため、訪問前に電話 093-600-2323 または公式情報での確認を推奨する。",
