  kicker: "KITCHEN KEN KAGOSHIMA",
  title: "鹿児島・草牟田のKitchen Ken。昼は洋食、夜はダイニングバーになる一軒",
  titleHTML: "草牟田で昼も夜も、<br><em>Kitchen Ken。</em>",
  subtitle: "草牟田で昼の洋食から夜の一杯まで使える、レンガ調のダイニング",
  lede: "鹿児島市の中心部から甲突川を渡り、城西・草牟田のあたりへ入ると、街の表情が少し落ち着く。大きな繁華街ではなく、住宅や学校、神社が並ぶ生活のエリアだ。鹿児島県護国神社のほど近く、草牟田二丁目の通り沿いに「Kitchen Ken（キッチンケン）」はある。昼はハンバーグやカレーといった洋食をしっかり出し、夜はレンガ調の店内で洋酒やダーツを楽しめるダイニングバーへと表情を変える、二つの顔を持った一軒だ。中心部の喧騒からは少し離れているぶん、近所の人が普段使いで通い、夜は遅い時間までゆっくり過ごせる。観光で歩く街というより、地元の暮らしのそばにある店だ。昼にしっかり食べたい日も、夜に一杯やりたい日も、同じ一軒で受け止めてくれる――そんな懐の広さがこの店の持ち味だと思う。",
