      desc: "メニューを覗くと、洋食店の定番がきちんとそろっているのが分かる。鹿児島らしい黒豚を使ったカツカレー、じっくり煮込んだビーフシチューのセット、看板のハンバーグコースなど、何を頼むか迷う楽しさがある。黒豚は鹿児島を代表する食材で、それを揚げてカレーに合わせる一皿は、地元で食べる洋食ならではの満足感がある。セットものはご飯やスープ、デザート、ドリンクまで含まれる構成になっていて、前菜から甘味までを一皿で完結させられるのがうれしい。昼に重めの洋食を食べたい日も、夜に酒と合わせて軽くつまみたい日も、その時の気分でメニューを選べる幅がある。一品ごとの内容や価格は時期で変わる可能性があるため、最新のメニューや料金は訪問前に公式情報で確認しておきたい。何度か通ううちに、自分の定番が決まってくる――そういう付き合い方のできる店だ。正直、こういう気負わず通える洋食店は、近所にあると重宝する。",
