      desc: "すすきの浪花亭は、すすきのの喧騒の中にありながら、落ち着いて食事に集中できる和食の設えでまとめられている。個室が用意されており、まわりを気にせず会話を楽しみたい接待や会食、家族の集まりに向く。店では慶事や法要といった、あらたまった席にも応じてくれるため、人生の節目を和食でしつらえたいときに頼りになる。記念日のサプライズに対応してくれる点も、特別な日の食事処として心強い。すすきので少人数の静かな会食をしたいとき、賑わいを避けて個室でゆっくり過ごせる和食の店という選択肢は、意外と貴重だ。大切な人との時間を、料理だけでなく空間ごと丁寧に扱ってもらえる――そういう安心感がある。会社の会食でも、家族の祝いの席でも、まわりを気にせず腰を落ち着けられるのはありがたい。席数や個室の広さ、対応できる人数は状況によって変わるため、用途や人数が決まっている場合は、予約の段階で相談しておくと当日の段取りが整う。",
      images: [],
