      desc: "梟があるのは、花畑町の一楽ビル2階。通り沿いの賑わいから一段上がったところにあるぶん、腰を落ち着けて飲み食いに集中しやすい。流行を取り入れた居酒屋ダイニングという業態らしく、肩肘張らずに過ごせる雰囲気で、ていねいな接客で迎えてくれるのが居心地のよさにつながっている。仕事帰りに同僚と軽く一杯という日にも、友人同士で賑やかに料理を囲む夜にも、無理なくなじむ。名物のつくねやチーズダッカルビは取り分けて食べやすいので、何人かで来てあれこれシェアするのに向いている。一人でカウンター的に静かに飲みたい夜から、グループでわいわい楽しみたい夜まで、人数や気分で表情を変えられるのが居酒屋ダイニングの強みだ。花畑町で「気軽だけれど、ちょっといい一品もある店」を探しているなら、ちょうどよく収まる一軒だと思う。席の種類や人数の対応は状況によって変わるため、大人数で行くときや個室を希望するときは、予約のときに相談しておくと当日の段取りが整う。",
