  lede: "大阪駅・梅田から環状線でひと駅。福島は、オフィス街の便利さと、夜になると路地裏に灯がともる飲食店街の顔をあわせ持つ街だ。昼間は淡々とした通りが、夕方を過ぎると一軒一軒の暖簾に人が吸い込まれていく。そんな福島七丁目、JR福島駅から歩いて3分ほどの場所に、鮨ふみはある。スリーエスビルの1階、檜のカウンターをメインの舞台にした江戸前鮨の店だ。大将は福喜鮨の本店や高級ホテル、北新地で20年の研鑽を積んだ職人で、その日その時の良質なネタをおまかせで握る。梅田で飲む前のひと皿ではなく、ここを目的に福島まで足を運びたくなる――そんな一軒だと思う。",
