      purpose: "他店と違う個性を知りたい人へ",
      desc: "鮨ふみが他の鮨店と一線を画すのは、メインの舞台となる檜のカウンターのつくり込みにある。照明の落とし方から席の高さまで緻密に計算されていて、握りを目の前で受け取る所作が美しく見えるように設えられている。カウンターには四季の花木が活けられ、著名な作家の酒器が使われるなど、料理だけでなく目で楽しむ要素も丁寧に整えられているのが特徴だ。鮨をつまむという行為そのものを、ひとつの時間として味わってほしいという意図が空間の隅々に感じられる。福島という飲食店の多い街にあって、賑やかに飲む店とは違う、落ち着いて握りと向き合える場所を求める人にとって、この設えは通いたくなる理由になる。大将との距離が近いカウンターだからこそ、その日のネタについて尋ねたり、好みを伝えたりしながら食事を進められる。空間と料理と会話が一体になった時間を過ごせるのが、鮨ふみならではの個性だと思う。",
