      desc: "鮨ふみの食事は、おまかせコースを軸に進んでいく。その日その時の良質なネタを大将が見極めて、握りを中心に順を追って供してくれる構成だ。季節ごとに仕入れが変わるため、同じ時期に通っても旬の移ろいを皿の上で感じられるのが楽しみになる。あらかじめ品書きが固定されているわけではないので、苦手な食材やその日の気分があれば、相談しながら進められるのもありがたい。一品料理にも相談で応じてもらえるため、握りの前に少しつまみたい、酒に合わせて一皿欲しい、といった希望も伝えやすい。価格帯はおまかせの内容によって幅があり、コースの構成や料金は時期や仕入れによって変わる可能性があるため、予約のときに確認しておくと当日が安心だ。夜は料理のラストオーダーが21時30分なので、ゆっくりおまかせを通したい場合は、早めの時間に入って腰を据えるのがおすすめだ。何が出るかを職人に委ね、その日の鮨を味わう――そんな食事の楽しみ方ができる一軒だと思う。",
