      desc: "美奈吉があるのは、京阪本線の大和田駅から徒歩8分ほどの住宅街の中だ。改札は1階に一か所だけで、駅前のバス停沿いに進み、グルメシティを左に見ながら路地を入っていく。少々入り組んだ道のりで、店主も迷ったら電話をと案内しているほどなので、初めてなら地図を確かめながら向かいたい。大和田駅には普通と区間急行が停まる。大阪方面からは京橋で京阪に乗り換え、守口市で各駅停車に乗り継ぐとスムーズだ。京都方面からは萱島での乗り換えが分かりやすい。繁華街の喧騒から離れた下町の路地そのものが、この店へ向かう道中の風景になる。普段は通らない住宅街を歩き、たこ焼き屋の角を曲がってたどり着く――その過程も含めて、わざわざ訪ねる楽しさがある。夜の営業は18時から22時頃まで、定休は水曜と木曜で、水曜は予約があれば営業する。予約優先のため、訪れる前に072-882-3355へ電話で確認しておくと確実だ。営業時間や料金は変わる可能性があるので、あわせて確認しておきたい。",
