      area: "藤井寺市野中",
      purpose: "実際に訪ねるときの道順を知りたい人へ",
      desc: "麺屋 工藤 藤井寺店があるのは、大阪府藤井寺市野中5-4-25。藤井寺市の南寄り、住宅と古墳が点在する野中エリアの一角だ。最寄りは近鉄南大阪線の藤井寺駅で、店までは約1.5km、歩くと18分ほど。同じく南大阪線の古市駅からも1.5kmほどで徒歩19分前後と、どちらの駅からも少し距離がある。そのぶん4台分の駐車場が用意されているので、車で訪ねるのが現実的だ。バスを使うなら、店の近くの野中北バス停からは徒歩3分ほどで着く。このあたりは、世界遺産に登録された古市古墳群の懐にあたる地域で、野中宮山古墳をはじめ大小の古墳が街なかに溶け込んでいる。古墳めぐりや藤井寺の散策と組み合わせ、歩き回ったあとの一杯としてこの店に立ち寄る、という使い方もしっくりくる。営業時間は昼が11時から14時半（ラストオーダー14時）、夜が17時から21時半（ラストオーダー21時）で、定休は木曜とそのほか不定休。営業時間や定休日、料金は変わる可能性があるので、出かける前に電話072-937-7277で確認しておくと安心だ。",
