  lede: "新潟市の中心部から阿賀野川を越えて南へ、亀田バイパスが住宅と商業施設のあいだを貫いていく。江南区曙町はそんな車の流れに沿った一帯で、買い物の行き帰りや仕事終わりにふらりと立ち寄れる距離感がある。焼肉タカ屋は、このバイパス沿いに店を構える焼肉店だ。看板に掲げるのは自家製の手作りダレと、肉の鮮度と質への自信。テーブルごとに仕切りを設けた半個室仕立ての店内は、家族の夕食にも、気のおけない仲間との一杯にも収まりがいい。火曜から金曜は夜だけ、土日祝は昼から通しで開ける営業のかたちも、暮らしのリズムに寄り添っている。週末の昼に満腹ランチで腹を満たすか、平日の夜にタレの染みた肉で一日を締めるか――使い方の幅が広い一軒を、味から席、アクセスまで順にたどっていく。",
