  lede: "宮崎市の中心は、橘通りを軸に飲食店と商店が連なる繁華エリアだ。アーケードと並木が続く通りを宮崎駅の西口から南へ歩くと、十分ほどで橘通東三丁目あたりに着く。この一角に、宮崎で初めての牛かつ専門店として開いたのが牛かつ なかざきだ。宮崎は牛肉どころとして知られるが、その肉を専門店の一皿でじっくり味わえる場所はそう多くない。揚げたての衣の中に赤身がレアに残る一切れを、各席に置かれた石板で自分の好みまで焼きながら食べる——そんな食べ方を軸にした店で、昼の早い時間から夜まで開いている。出張帰りの一人客から、宮崎牛を目当てに訪れる家族連れまで、使い方の幅が広い。橘通りで肉を、と考えたときに覚えておきたい一軒について、編集部の視点で見ていきたい。",
