      desc: "なかざきの牛かつは、およそ六十秒だけ揚げて中心を赤いまま残す仕立てだ。運ばれてきた時点ではレアで、衣の下から赤身がのぞく。各席には熱した石板が用意されていて、切り分けた断面を自分でじっくり焼きながら、好みの火の通りまで持っていける。レアのまま肉の味を楽しむ人もいれば、表面をしっかり焼いて香ばしさを足す人もいて、一皿の中で焼き加減を変えながら食べ進められるのがこの店の食べ方だ。揚げ物でありながら脂に頼らず、赤身そのものの旨みを主役に置いているので、最後まで重くなりにくい。出てきたものをただ食べるのではなく、自分の手で仕上げるという一手間が入るぶん、食事に参加している感覚が残る。これ、地味に満足度が高い。火の通し方は好みで決められるので、肉の状態を見ながら焼くのが楽しい。最初の一切れは何もつけずに肉そのものの味を確かめ、そこから焼き加減や薬味を足していくと、味の変化が分かりやすい。衣は薄めで、肉と衣のバランスが赤身寄りに振れているのも専門店らしい組み立てだ。",
