      area: "熊本市南区薄場",
      purpose: "本格イタリアンを目的に店を選びたい人へ",
      desc: "ピノッキオの料理を支えているのは、店主がイタリアで過ごした修業の時間だ。若い頃にイタリア北西部、アルプスのふもとに広がるアオスタの街で腕を磨き、その手仕事を熊本に持ち帰った。だから出てくる一皿は、見た目の華やかさで押すのではなく、素材と調理の積み重ねで食べ手を納得させる料理になっている。パスタは手打ちで、生地の食感そのものがごちそうになる。前菜には、生のトマトをのせた香ばしいクロスティーニや、人参をじっくり煮含めたポタージュといった、家庭的でありながら手のかかった品が並ぶ。ひと皿ずつ丁寧に組み立てていくその姿勢が、わざわざ足を運ぶ理由になる。本場で過ごした人がつくる料理を、構えずに味わえる——それがこの店のいちばんの芯であり、昼の一食を特別なものに変えてくれる。背伸びして訪ねる店ではないのに、食べ終えるころには、わざわざここまで来てよかったと思える。その手応えが、最初の一皿からきちんと伝わってくるのが、ピノッキオという店の確かさだ。",
