      name: "昼のコースが、通う口実になる",
      cuisine: "ランチ・コスパ",
      area: "熊本市南区薄場",
      purpose: "普段使いで通える店を探している人へ",
      desc: "この店が地元で親しまれている大きな理由が、昼のランチにある。コースは内容の異なる二種類が用意され、前菜からデザート、食後の飲み物までがひと続きで楽しめる構成になっている。デザートはいくつかの種類から選べる日もあり、最後まで気分よく食べ終えられるのがうれしい。本格的なイタリア料理がこの値段で味わえるのか、と驚く声が地元の食べ手から上がるのも、内容と価格の釣り合いが取れているからだ。気負わず入れて、それでいて満足度の高い昼食になる——この距離感が、一度きりではなく何度も足が向く店をつくっている。仕事の合間でも、休日の昼でも使えるので、まずはランチで店の実力を確かめる人が多い。近所で働く人が昼の定番に組み込んでいたり、少し足を延ばして通う常連がいたりと、この一食を目当てにする人の層は幅広い。昼どきは席が埋まりやすいので、時間に余裕を持って向かいたい。料理の内容や価格は時期で動くことがあるので、訪れる前に電話で確かめておくと安心だ。",
      images: ["/restaurants/teleapo-ピノッキオ/point2.jpg"],
