  titleHTML: "<em>Giselle</em>、<br>花畑の小さな寄り道。",
  subtitle: "海外アンティークと手芸小物が並ぶ、久留米・花畑の雑貨&カフェ",
  lede: "久留米の中心、西鉄花畑駅から歩いて数分。商店や金融機関が並ぶ花畑の通りに、フランスや欧米から渡ってきたアンティークと、淹れたての珈琲が同居する一軒がある。Giselle ジゼル 雑貨屋&カフェは、二〇二三年の春にこの花畑三丁目で店を開いた、雑貨屋とカフェがひとつになったお店だ。リボンやボタン、ペーパーナプキンといった手芸の小物から、一点ものの古い雑貨まで、棚の隅々まで見て回る楽しさがある。気になるものを手に取ったあと、そのまま腰を下ろして珈琲やスイーツで一息つける――その二つの時間が地続きになっているのが、この店の心地よさだ。木曜から土曜という限られた日にだけ扉を開く、久留米の街なかに小さな寄り道をつくってくれる場所である。",
