  quoteCite: "マチノワ編集部",
  closing: "学生街の昼に寄るか、一日の終わりに夜の一皿を求めて寄るかで、こあの助の使い方は変わってくる。昼に訪ねるなら、ライス付きのカレーや名物の丼を手早く一皿、というのが収まりがいい。営業は火曜から金曜が中心で、月曜と土日は休みにあたるので、週末しか動けない人は曜日を確かめてから向かいたい。グリーンカレーかイエローカレーか、それともガパオや豚納豆丼か――迷ったら、まずは看板のタイカレーから入って、次に来たときに丼へ広げていくと、タイと日本を行き来するこの店の面白さが見えてくる。辛さは段階で選べるので、自分の適量を一度つかんでおくと、二度目からの注文が楽になる。一人なら二階で手早く、軽く食事をするなら気の置けない相手と――どちらの使い方にも応えてくれる。所要は混んでいなければ三十分ほど、昼のピークなら待ち時間を含めて見ておくと気が楽だ。出町柳駅から歩いて十分前後、百万遍や京大を目印に向かえば迷わない。鴨川のデルタや古書店をめぐる左京区散歩の途中に、この店の一皿を組み込んでみてほしい。",
