      name: "台湾で腕を磨いた店主が、地元の近くで打つ一杯",
      cuisine: "店主・成り立ち",
      area: "西宮市門戸荘",
      purpose: "通いたくなる理由、店の背景を知りたい人へ",
      desc: "通いたくなる理由を語るうえで外せないのが、店主・野条さんの来歴だ。野条さんは兵庫の出身でありながら、活動の拠点を台湾に置き、日本式ラーメン店「麺処 田冶」を営んできた。現地ではテレビで紹介されるほど知られた存在になり、ラーメンの作り手を育てる学校まで運営している。つまりこの一杯は、日本のラーメンを海の外に伝え続けてきた人が、母国の近くに戻って打ち出した味なのだ。日本で修業して日本で店を出すのとは、たどってきた道のりが違う。台湾で多くの人に受け入れられる味を組み立ててきた経験は、誰にでも届く分かりやすさと、専門店としての芯の強さの両方に表れている。地元・西宮の駅前で、海を渡って磨かれた鶏白湯が食べられる――この物語性こそ、一度きりで終わらせず、また暖簾をくぐりたくなる理由になっている。海外で評価された味が、いまは門戸厄神の駅前で待っている。",
