      desc: "麺屋野条のこだわりは、カウンターに座ると目に飛び込んでくる。席の正面に、播州龍野の醤油が並べられているのだ。龍野は兵庫県たつの市を中心に古くから醤油づくりが盛んな土地で、淡口醤油の産地として知られる。その地の醤油を客の目の前に置くという見せ方は、鶏のスープを支える調味の土台を地元・兵庫の素材から組み立てているという、作り手の意思表示でもある。鶏白湯という濃厚なスープに、産地のはっきりした醤油を合わせる――その掛け合わせが、この店の一杯の輪郭を決めている。専門店だからこそ、スープだけでなく、それを締める醤油やかえしの一つひとつにまで目が届く。メニューや内容は時期で動くことがあるので、季節限定の品や仕込みの変化が気になるなら、訪れる前に店の案内を確かめておくといい。素材の出どころが見える一杯は、食べ終えたあとの納得感が違う。これ、地味に効く部分だと思う。",
