      desc: "具体的な楽しみは、おまかせコースの組み立てにある。先付けに始まり、お造り、火を入れた逸品、そして主役の握りへと進み、最後はお椀とデザートで締める――前菜から甘味までをひと続きに構成した流れが、この店のコースだ。握りは小ぶりのつまみで終わらず、コースの軸としてしっかりした貫数が用意され、お造りや逸品と握りの両方を一度の食事で味わえる。沖縄の鮨屋でありながら、構成そのものは正統的なおまかせの形を取っているのが特徴だ。価格はコースの内容や品数によって幅があり、おおよそ数千円台後半から一万円台までの設定が中心になる。仕入れや季節で内容が動くため、当日のネタや料金が気になる場合は、予約の段階で確認しておくと安心だ。何品もの皿が順に運ばれてくるので、ゆっくり時間をとって臨みたい。急いで食べ切る店ではなく、ひと皿ごとの間合いを味わう店だと思っておくといい。これ、地味に効く心構えだ。",
