      desc: "店があるのは那覇市寄宮二丁目、県道46号線沿いのSYシリーズ寄宮の一角だ。国際通りや牧志といった観光の中心からは南へ少し離れた、生活の匂いのする住宅地にある。ゆいレールを使うなら安里駅あたりから歩いて向かう形になるが、距離はそれなりにあるので、車やタクシーでの来店も選びやすい。駐車場は近隣の大原病院と共同で用意されているため、車で訪ねたい人にも対応している。予約方法が幅広いのもこの店の特徴で、電話のほか、LINEやInstagramのダイレクトメッセージ、ショートメールなどから席を押さえられる。完全予約制なので、ふらりと立ち寄るのではなく、行く日を決めてから連絡するのが基本の使い方だ。五席しかないぶん、週末や記念日が重なる時季は早めに動いておくほうが、希望の日に席を取りやすい。営業の時間帯や定休は時期によって変わることがあるため、予約の連絡をとる際に、その日の営業と空き状況をあわせて聞いておくと確実だろう。観光ルートから少し外れた寄宮まで足を延ばす、その小さな寄り道の先に、五席の鮨屋が待っている。那覇の街を南へ少し歩く、その距離そのものが、特別な一席への助走になっている。",
