      desc: "通いたくなる理由を挙げるなら、昼と夜でまったく違う使い方ができることだ。昼は蕎麦と丼で手早く満たす食事の場として機能し、夜になると一品料理を肴に蕎麦と酒を楽しむ、いわゆる蕎麦呑みの場へと表情を変える。店名に「バー」を冠しているだけあって酒の用意は幅広く、蕎麦の前に軽く一杯やってから締めに手繰る、という大人の流れがそのまま叶う。店主はお客のリクエストになるべく応えられる店にしたかったと語っており、その姿勢は幅広い年齢層への目配りにも表れている。子供椅子も用意されているため、家族での外食にも使いやすい。ひとりで来てカウンターで静かに手繰るもよし、仲間と夜に長居するもよし。同じ店なのに、訪ねる時間と人数で別の顔を見せてくれるから、生活の中で何度でも出番がある。これ、地味にありがたい。",
