  sideArticles: [],
  quote: "SUNABARは、小倉南区日の出町の住宅街で、昼は手打ちの二八蕎麦、夜は蕎麦呑みの一軒として二つの顔を持つ店。守恒駅から歩いて五分、競馬場にほど近い生活の街で、一人でも家族でも気負わず通える距離感がいい。守恒で蕎麦をと思ったら、思い出してほしいお店です。",
  quoteCite: "マチノワ編集部",
  closing: "守恒駅から住宅街を五分ほど歩いた先、小倉競馬場のそばに店があると分かっていれば、この一軒は驚くほど使い勝手がよくなる。昼に訪ねるなら、鴨南そばや肉ごぼう天そばを軸に、足りなければ親子丼やカツ丼のセットを合わせて、手早く満たす食事の場として。夜に向かうなら、一品料理を肴に酒を一杯やってから蕎麦で締める蕎麦呑みの流れがいい。腰を据えるつもりなら、飲み放題のついた豚しゃぶコースを選ぶと長居がはかどる。一人ならカウンターで静かに手繰り、家族連れなら子供椅子のある小あがりへ。車で来る人は三台分の駐車場を、モノレール派は守恒駅からの五分を見込んでおきたい。昼と夜で営業時間が分かれ、定休日もあるので、行く日が決まったら当日の営業と気になるメニューをあわせて確かめておくと確実だ。競馬開催日にあわせるのも、仕事帰りにふらりと降りるのも、この街ならではの寄り道になる。守恒に蕎麦の一軒を覚えておきたい人に、ちょうどいい店だ。",
