  subtitle: "湯あがりにふらっと一杯、道後温泉のハイボール酒場",
  lede: "道後温泉の湯けむりを抜けて、まだ火照った体のまま夜の商店街へ出る――そんな時間に、ちょうど一杯やりたくなる場所がある。2025年10月、道後温泉別館の飛鳥乃湯泉の目の前にオープンした道後ハイボール酒場は、観光のしめにふらっと立ち寄れるカジュアルな飲み屋だ。湯あがりの高揚をそのまま持ち込んで、よく冷えたハイボールで喉を鳴らす。難しい作法も予約もいらず、一人でも気軽に暖簾をくぐれる空気がある。松山市道後町一丁目、道後温泉駅から商店街を抜けてすぐという分かりやすい立地で、温泉と土産物店と飲み屋が徒歩圏に集まる道後の中心にこの店は位置している。湯の街を歩き切った足で、最後にどこで一服するか。その答えになってくれる一軒を、湯あがりの動線とあわせて見ていきたい。",
