      desc: "旅先で覚えておきたくなる理由は、その入りやすさにある。カジュアルな構えで、一人でもふらっと暖簾をくぐれる空気が流れている。観光地の飲み屋というと、団体や予約で埋まっていて一見では入りにくい、という場面も少なくないが、ここは湯あがりの軽装のまま立ち寄れるくらいの気軽さで迎えてくれる。連れがいてもいなくても、長居しても一杯で切り上げても、過ごし方を客の側に委ねてくれる懐の深さがある。観光のしめにと気負わず、街を歩いていてふと喉が渇いたから、という軽い動機で入れるのがいい。旅の途中、予定と予定のあいだにできた小さな空き時間を、無理なく埋めてくれる。気軽に一杯やって、また夜の散歩に戻る――そんな使い方ができる店は、観光客にとってありがたい存在だ。気構えずに扉を開けられる、その敷居の低さが何よりの持ち味になっている。",
