      desc: "店があるのは松山市道後町一丁目、道後温泉の中心エリアだ。伊予鉄道城南線の道後温泉駅から商店街を抜けて歩いてすぐ、飛鳥乃湯泉の目の前という分かりやすい立地にある。松山市駅や大街道から路面電車に揺られて道後温泉駅で降り、ハイカラ通りの愛称で知られる道後商店街を冷やかしながら歩けば、自然とこの界隈にたどり着く。終着駅前には坊っちゃん列車や放生園の足湯、からくり時計といった見どころも集まっていて、駅から店までの道のりそのものが道後観光の一部になっている。日中は道後温泉本館や飛鳥乃湯泉で湯を楽しみ、夕暮れに商店街を歩き、その流れの最後にこの店で一杯――という一日の組み立てがしやすい。営業時間や定休日は変わることがあるため、夜遅くまで楽しむつもりなら、来店前に最新の営業を確かめておくと段取りが立てやすい。湯の街を歩き切った足で、最後にたどり着く一杯がここにある。",
