      desc: "具体的な楽しみとして名前が挙がるのが、鴨を合わせた蕎麦だ。温かい出汁に鴨を浮かべた鴨南蕎麦や、つけ汁で手繰る鴨せいろは、鴨の脂の甘みと出汁の旨味が蕎麦に絡み、冷たい蕎麦とも温かい蕎麦とも違う満足感を残す。鴨と蕎麦は古くから相性のいい組み合わせとして知られ、蕎麦そのものの香りを軸にしながら、鴨のコクで一杯に厚みを持たせてくれる。せいろで蕎麦本来の風味を確かめるか、鴨で旨味を重ねるか――その日の気分で振れ幅があるのがいい。粉から仕立てる蕎麦専門店だけに、つゆや出汁にも蕎麦に寄り添う配慮が感じられる。迷ったら、まず蕎麦の素の味をせいろで確かめてから、次の一枚で鴨に進むという順番も楽しい。冷たい蕎麦で麺のコシと喉ごしを味わう日もあれば、温かい蕎麦で出汁ごと体を温めたい日もある。その振れ幅に応えてくれる懐の広さがある。メニューや価格は時期で動くことがあるので、気になる一品があれば訪れる前に確かめておくと確実だ。",
