      desc: "店があるのは久留米市宮ノ陣町五郎丸、宮ノ陣の田園地帯の一角だ。最寄りは西鉄甘木線の学校前駅で、歩いて数分ほどと電車でも訪ねやすい。久留米の市街地からは少し離れた田んぼ道沿いにあり、ふらりと通りかかって入るというより、目的地として足を向ける店になる。車で向かう人も多いエリアで、のどかな風景の中を進んだ先に、しっかりとした構えの一軒家が現れる。宮ノ陣は久留米の北部、筑後川にもほど近い落ち着いたエリアで、観光の動線というよりは生活と田園の風景が広がる土地だ。昼の営業時間に合わせて訪ね、蕎麦をゆっくり味わってから、周辺をのんびり巡るのもいい。久留米の中心で買い物や用事を済ませた帰りに、少し足を延ばして昼の蕎麦を手繰る――そんな組み込み方もできる。昼だけの営業で火曜と水曜が定休となるため、訪れる日が決まったら当日の営業を確かめてから動くと取りこぼしがない。学校前駅から店までの数分、田園の景色を眺めながら歩くこと自体が、この一軒へ向かう小さな道行きになる。",
