      cuisine: "店内とテイクアウト",
      area: "白石区北郷",
      purpose: "通いたくなる理由、店の使い分けを知りたい人へ",
      desc: "通いたくなる理由を挙げるなら、店で呑む夜と、家で囲む夜の両方に応えてくれることだ。店先には「お持ち帰り電話」と番号が大きく掲げられ、電話で頼んでおけば焼きたての串を持ち帰れる。実際、アルミホイルに包まれた串がぎっしり詰まった折は、家の食卓でそのまま広げても画になる。仕事帰りにカウンターで一杯やって帰る日もあれば、家族の待つ家へ折を提げて帰る日もある――同じ店が、その日の気分でどちらの役にも回ってくれる。北郷のような住宅地では、この使い分けができる焼き鳥屋の存在がありがたい。店で炭の香りと活気を浴びたい夜と、家でくつろぎながら串をつまみたい夜。どちらにも開かれているから、生活の中で何度でも出番がある。持ち帰りは電話で予約しておくと受け取りがスムーズだ。串の本数や内容、受け取りの時間は、注文のときに相談しておくと当日慌てずに済む。これ、地味に効く。",
