      cuisine: "アクセス・周辺",
      area: "白石区北郷",
      purpose: "実際に行くときの道順と段取りを知りたい人へ",
      desc: "店があるのは札幌市白石区北郷三条十二丁目、サニープレイスという建物の一階だ。JR千歳線の平和駅からは三百メートルほど、歩いて数分の距離にある。駅から店までは住宅と商店が混じる生活道路で、夜にはぽつぽつと灯りがともる落ち着いた道のりだ。観光の動線からは外れた街なので、ふらりと通りかかって入るというより、目的地として足を向ける店になる。仕事や買い物の帰りに平和駅で降りて炭火の一杯を手繰る、休日に家族で夕飯を兼ねて立ち寄る、あるいは家で食べる串を電話で頼んで受け取りに寄る――北郷という街の夜に、自然と組み込める一軒だ。車で向かう人は、周辺の駐車事情をあらかじめ確かめておくと当日慌てずに済む。北郷は札幌の市街地からやや東に離れた住宅地で、夜は静かで落ち着いている。その静けさの中に炭火の灯る店があるというだけで、街の夜のちょっとした目的地になる。店までの数分の道のりそのものが、この一軒へ向かう小さな助走になる。",
