  lede: "那覇の中心、国際通りから少し北へ抜けると、前島という街がある。国道58号と泊港にはさまれた一帯で、オフィスやマンションが立ち並びながら、路地に入れば古くからの食堂や個人店が点在する、生活の匂いの濃いエリアだ。ゆいレールの美栄橋駅から歩いて数分、その前島の一角に「ラーメンうずまき」はある。二〇二四年六月、与那原町から移ってきた醤油ラーメンの店だ。カウンターとテーブルを合わせて十四席ほどの小さな構えで、昼は近隣で働く人の食事どきに、夜は一杯を手繰りに立ち寄る人で席が埋まる。観光の喧騒から半歩離れた街で、地元の生活に溶け込みながら一杯を出し続ける――そんな店の輪郭を、ここから順に追っていきたい。",
