  title: "札幌・白石区北郷の昼を満たす定食店、信ちゃんママ。ドリンクとデザートまで付く、まちの台所",
  titleHTML: "信ちゃんママ、<br>北郷の<em>昼。</em>",
  subtitle: "白石区北郷、昼だけ開く定食店。北海道の食材を一食に",
  lede: "札幌の都心から少し外れた白石区北郷は、住宅と小さな商いが静かに混ざり合う生活のまちだ。その北郷三条のビル二階に、昼だけ暖簾を上げる定食店がある。信ちゃんママ――名前のとおり、ママが厨房を預かり、近隣で働く人や地元の常連が、昼の一食を目当てに階段を上ってくる。焼き魚やフライ、ハンバーグに生ラムジンギスカンまで、品書きは家庭の食卓のように幅広い。しかも、どの定食を頼んでもドリンクとデザートが付いてくる。慌ただしい昼休みに、最後の甘味まで満たされて店を出られる――そんな、まちの台所のような一軒だ。",
