      area: "札幌市白石区北郷",
      purpose: "昼の一食を、一つの席で気持ちよく完結させたい人へ",
      desc: "信ちゃんママの献立で、まず頭に入れておきたいのが「すべての定食にドリンクとデザートが付く」という決まりだ。焼き魚でもフライでも、メインの一皿を選べば、そこに飲み物と甘味まで自動的に揃う。昼の定食といえば主菜と味噌汁、漬物で完結する店が多いなかで、この一手間は地味に効く。食後のコーヒーを別の店に探して歩く必要がなく、デザートで一息ついてから午後に戻れる。働く人にとって、昼休みの限られた時間を一つの席で完結できるのは、思いのほかありがたい。価格帯も焼き魚定食の六百円台から、と昼食として無理がない。品数で盛るのではなく、一食の満足度を最後まで設計している――そこに、この店が長く通われてきた理由が見える。料金や品書きは時期で動くことがあるので、訪れる前に電話で確かめておくと確実だ。",
