      purpose: "日替わりで通っても飽きない店を探している人へ",
      desc: "二つ目の魅力は、献立の幅の広さにある。焼き魚定食やミックスフライ定食といった定番に加えて、白老牛を使ったハンバーグ定食、生ラムのジンギスカン定食まで、北海道の食材を昼の一皿に落とし込んだ品が並ぶ。ジンギスカンといえば夜の炭火や宴席の印象が強いが、ここでは昼の定食として、ごはんと一緒に気軽に味わえる。観光で土地の名物を探す人にとっても、近所で働く常連にとっても、その日の気分で和洋・肉魚を選び分けられる懐の深さがある。日替わりで通っても飽きが来にくいのは、こうした品揃えがあってこそだ。ママが厨房を回す家庭的な定食店でありながら、土地の食材をきちんと取り込んでいる点に、北郷という生活圏で根を張ってきた年月がにじむ。メニューは季節で入れ替わることもあるため、来店前に最新の品書きを確かめておきたい。",
