  sideArticles: [],
  quote: "沖縄ラーメン いっとは、那覇・久茂地の夜をそっと支える一軒。自社で挽く麺と塩の一杯を、昼の合間にも、飲んだあとの深夜にも差し出してくれる。締めの場所をどこにするか、久茂地で迷ったら、思い出してほしい店です。",
  quoteCite: "マチノワ編集部",
  closing: "久茂地で過ごす一日のどこにこの一杯を置くかで、いっとの楽しみ方は変わってくる。観光で昼に動くなら、国際通りや県庁前を歩く途中、十一時すぎの口開けを狙ってうま塩を手繰っておくと、午後の街歩きが軽くなる。一人なら、塩か辛かを選んで、替え玉まで含めて二十分から三十分も見ておけば足りる。本領が出るのはむしろ夜だ。松山や国際通りで飲んだあと、終電やタクシーの前にもう一杯。深夜まで開いているこの店は、その締めをきっちり引き受けてくれる。二人以上で訪れるなら、塩と辛を一杯ずつ頼んで味の方向を分け合うのも楽しい。予算は一杯あたり千円前後を目安にしておけば、島人セットを付けても大きくは外れない。最寄りの美栄橋駅から歩いて五分、バイクなら店裏の無料駐輪場が使える。水曜が定休で、夜は時間が深いぶん、ピークと終了間際の混み具合は読みにくい。営業時間やメニューは時期で動くことがあるので、深夜を狙うときほど、出かける前に最新の情報を一度確かめておきたい。久茂地の夜に、帰り道の一杯としてちょうどいい場所だ。",
