      desc: "木下は夜の営業が中心の店だ。予算の目安はひとり三千円台と紹介されており、和食をきちんと味わいながらも、毎日の暮らしの中で手が届く範囲に収まっている。記念日のためのかしこまった一軒というより、一週間の真ん中に立ち寄って、その日の疲れをそっとほどくのに向いた価格帯だと思う。仕事を終えて、まだ家に帰るには少し早い夜。改札を出て、一品とお酒を一杯。そんな使い方が似合う。和食の店だから、料理に合わせて日本酒や晩酌をゆっくり傾けるのもいい。一週間がんばった自分への小さなご褒美として、金曜の夜にひとり静かに一杯——そんな使い方にもちょうど収まる価格帯だ。背伸びしすぎず、それでいて家飲みとは違う満ち足りた時間が手に入る。何をどれだけ頼むかで支払いは上下するので、はじめての夜は軽めに始めて、店の調子をつかんでいくのが収まりがいい。営業時間や定休日は変わることがあるため、夜遅めを狙うときほど、訪れる前に電話で確かめておくと無駄がない。",
