      purpose: "どんな雰囲気でどう過ごせるか知りたい人へ",
      desc: "店の空気は、料理の来歴をそのまま映している。古いアメリカと沖縄が溶け合ったような、どこか懐かしい設えのなかで、欧米の家庭に招かれたような温かさで迎えてくれる——そう語られてきた店だ。きらびやかな高級レストランではなく、肩の力を抜いて長居できる食堂の気安さがある。だからこそ、一人で昼にふらりと立ち寄って黙々とプレートを平らげるのも似合うし、家族連れで賑やかにテーブルを囲むのも収まりがいい。子ども連れの普段使いから、年配の常連がいつもの席で過ごす午後まで、客層の幅が広いのもこういう店の強みだ。観光の途中に地元の暮らしの匂いを感じたい旅行者にとっても、こうした一軒は記憶に残りやすい。流行の内装に作り替えるのではなく、長い時間が自然に染み込んだ空間そのものが、この店のもてなしになっている。誰と来ても気負わずに過ごせる——それが、辻でこの店が果たしてきた役割だ。",
