  title: "福岡・城南区友泉亭の珈琲とキャンプギア。シーンで選ぶ一杯を提案する、川内珈琲 by camp gear 12",
  titleHTML: "川内珈琲 by camp gear 12、<br>友泉亭の<em>一杯。</em>",
  subtitle: "コーヒーとアウトドアを結ぶ、城南区の提案型珈琲店",
  lede: "福岡市城南区、友泉亭という地名は、江戸期の大名庭園「友泉亭公園」に由来する。市街地の喧騒からは少し離れ、住宅と緑が静かに同居するエリアだ。その友泉亭に居を構えるのが、川内珈琲 by camp gear 12。名前のとおり、ここはコーヒーとキャンプギアという二つの軸を持つ店で、豆は朝の一杯、食後の一杯、特別な日の一杯、そしてアウトドアの一杯と、飲む場面ごとに選び分けられるよう並べられている。日々のコーヒーを淡々と消費するのではなく、その日の時間や気分に合わせて一杯を選ぶ——そんな飲み方を提案する一軒だ。豆はケニアやエチオピア、コロンビア、インドネシアなど産地ごとに揃い、ドリップパックから粉まで、生活のリズムに合わせて手に取れる。週末のキャンプに持ち出す一杯も、平日の朝の一杯も、同じ棚から選べるのがこの店らしさだと言える。",
