      purpose: "飲む場面から豆を選びたい人へ",
      desc: "川内珈琲の棚をのぞくと、まず目に入るのは産地の幅広さだ。ケニア、エチオピア、コロンビア、インドネシア、ブラジル——同じコーヒーといっても、産地が変われば香りも酸味もコクもまるで違う。この店はその違いを、難しい言葉で語るのではなく、いつ飲むかという切り口で並べている。すっきり目を覚ましたい朝の一杯、食事のあとに余韻を整える一杯、ゆっくり過ごす夜の一杯、そして外で淹れるアウトドアの一杯。飲む場面が決まれば、選ぶ豆も自然と絞られる。コーヒーに詳しくなくても、自分の生活のどの時間に置くかを思い浮かべれば、棚の前で立ち往生せずに済む。ドリップパックは一杯分から、豆は粉のまま少量からと、手に取りやすい単位で並ぶので、まずは気になる産地をひとつ試して、合えば次に深掘りしていくという付き合い方ができる。産地の知識を増やすための場所というより、自分の好みを少しずつ見つけていく場所だと言ったほうが近い。",
