      desc: "店が根を下ろす城南区友泉亭は、福岡藩主の別邸として開かれた庭園、友泉亭公園を中心に広がる落ち着いた住宅地だ。市街地のような人混みはなく、緑と暮らしの気配が静かに同居している。コーヒーをじっくり選んだり、これから始めるキャンプの道具を相談したりするには、こうした腰を据えやすい環境はちょうどいい。せわしない繁華街のなかでは、豆の産地をひとつずつ比べたり、ギアの使い方をたずねたりという時間は取りにくいものだ。友泉亭という街の速度が、この店の過ごし方とよく合っている。アウトドアに興味を持ちはじめた家族連れが週末に立ち寄るのも、コーヒー好きが一人でじっくり棚を眺めるのも、どちらも様になる。買い物のあとに友泉亭公園まで足をのばし、池をのぞむ庭を歩いてひと息つけば、自分が選んだ一杯を持ち帰る道のりまで含めて、ちょっとした遠出になる。落ち着いた街で、自分の時間の使い方を整えにいく——そんな感覚で訪れたい一軒だ。",
