      desc: "店内は、木の温もりが残るこぢんまりとした食堂だ。厨房に面したカウンターと、奥に置かれたテーブル席が並び、ベンチには縞模様のクッションが置かれている。一人で来てカウンターに腰掛け、黒板を眺めながら料理が運ばれるのを待つのにちょうどいい広さで、近所の人が連れ立って卓を囲むのにも無理がない。シェフが一人で厨房に立つため、店内には大げさな演出はなく、定食屋としての居心地のよさが前に出ている。窓には簾風のブラインドが下り、昼は柔らかい光が差し込む。カウンター越しには厨房がのぞき、コーヒーの道具や酒瓶が並ぶ棚が見える。仕込みの音や皿の触れ合う音が近くに届く距離感は、シェフ一人の店ならではのものだ。卓上にはその日の品書きを記した小さな札が立ち、席についてから黒板とあわせて眺めることになる。気取らず入れて、長居しても急かされない空気があるから、福岡大学や近隣に勤める人が一人の昼食に使い、夜は仕事帰りに一杯添えて寄る——そんな日常の使われ方が想像できる。テーブルの脇に置かれた縞のクッションや木の椅子は、家庭の食卓に近い親しみがあり、初めての人でも構えずに腰を下ろせる。家族での外食にも、ひとり客の気楽な一食にも開かれた、肩の力が抜ける場所だ。",
