  sideArticles: [],
  quote: "フレンチの厨房で腕を磨いたシェフが、油山のふもとで一人、定食屋の暖簾を掛ける。ビーフストロガノフやコンフィを千円台の定食に落とし込み、さしみの小鉢を添える折衷が、いかにも福岡の街場らしい。黒板を覗いて今日の一皿を選ぶ時間ごと、堤の日常に置いておきたい一軒だ。",
  quoteCite: "マチノワ編集部",
  closing: "昼に来るか、夜に来るかで、この店の表情はずいぶん変わる。はじめの一回は、黒板を端から読んでから席につくのがいい。仕込みに手のかかる煮込みやコンフィが書いてあれば、まずそれを軸に頼み、さしみの小鉢で口直しを挟むと、この店ならではの和洋の行き来が一食でつかめる。一人なら、カウンターで料理が仕上がるのを待つ昼が向く。近所の人や家族と来るなら、テーブルでゆっくり卓を囲み、夜は酒を一杯添えて長居するのも似合う。所要は、定食をきちんと味わうなら一時間ほど見ておきたい。シェフが一人で回しているぶん、混む時間は提供に間が空くことがあるので、急ぎの日より余裕のある日に合わせたい。油山観光道路沿いで専用の駐車場はないため、車なら停め先を、夜に確実に座りたいなら席の空きを、それぞれ先に確かめておくと当日あわてない。営業時間や定休、黒板の中身は時期で動くので、来店前に電話で最新を押さえておくと確実だ。油山のふもとまで足を伸ばす日の一食に、この定食屋を組み込んでみてほしい。",
