      purpose: "新鮮な魚を肴に飲みたい人へ",
      desc: "たから屋の核にあるのは、駿河湾で揚がった魚をいかに鮮度よく出すか、という一点だ。清水と由比の市場に足を運んで仕入れる魚は、季節ごとに顔ぶれが変わる。たとえば透き通ったあおりイカの刺身は、糸のように細く引かれて皿いっぱいに並び、噛むほどに甘みが立つ。赤甘鯛のような上品な白身を、焼き物に仕立てて出すこともある。日本でも有数の深さを持つ駿河湾は、浅場の魚から深海の魚まで幅広く揚がる海で、清水の市場にはその日その日で違う魚が並ぶ。だからこの店の刺身は、いつ来ても同じではない。何が出るかはその日の海と相談、という献立の組み方そのものが、港町の居酒屋らしい醍醐味になっている。駿河湾は湾のすぐ沖が深く落ち込む地形で、季節ごとに揚がる魚が大きく入れ替わる。清水や由比の市場には、近海の地魚から、その時季ならではの旬の魚までが並び、仲買を通して街の店へ届く。たから屋がその市場に通って魚を選ぶというのは、つまり、その日の駿河湾の状態がそのまま皿に出るということだ。刺身に何を選ぶか迷ったら、その日のおすすめを尋ねてみるのがいい。仕入れの良かった魚を、いちばん向く切り方で出してくれるはずだ。",
