      purpose: "顔ぶれの変わる一皿を楽しみたい人へ",
      desc: "創業からおよそ六十年、たから屋はいま三代目の手に渡っている。長く続く店にありがちな格式張った重さはなく、むしろ常連も初めての客も同じ温度で迎える空気が流れているのが、この店が地元で親しまれてきた理由だろう。品書きは固定されておらず、その日に揚がった魚や仕入れの具合で内容が動く。赤甘鯛の焼き物のように、火を通してこそ味が締まる魚は焼き物で、持ち味を生かす魚は刺身でと、同じ素材でも見せ方を変えてくる。だから前に来たときと違う一皿に出会えるし、今日は何があるかを確かめに来ること自体が、通う楽しみになる。茶碗蒸しやかき揚げといった、魚に寄り添う一品の用意もある。何代も同じ街で店を続けるというのは、その土地の海と客をよく知っているということだ。その積み重ねが、一皿ごとの安心感に表れている。",
