      purpose: "何を頼むか当たりをつけたい人へ",
      desc: "献立は、駿河湾の魚を軸にしながら、軽くつまみたい日もじっくり腰を据えたい日も受け止められるように組まれている。刺身で魚そのものを味わうのもいいし、赤甘鯛のような白身を焼き物にしてもらえば、ご飯にも酒にも合う一皿になる。出汁の効いた茶碗蒸しは、冷たい刺身のあいだに挟むと箸休めにちょうどよく、魚介のかき揚げは香ばしさで酒を進ませる。お通しから始まり、刺身、焼き物、揚げ物、蒸し物と、和食の引き出しをひと通り押さえているので、何人かで来て少しずつ分け合えば、その日の海の幸をいろいろと試せる。固定された看板メニューを追いかける店ではないぶん、その日の黒板や店の人のすすめに耳を傾けると、迷わず良い魚にたどり着ける。軽く一杯のつもりが、刺身から焼き物へと自然に進んでしまうのも、魚の質に引っぱられてのことだろう。最初の一品に迷ったら、まずはその日の刺身を頼み、海の様子をうかがってから次を組み立てるのが収まりがいい。料理の内容や値段は仕入れや時期で動くので、目当ての魚があるなら、訪れる前に電話で確かめておくと空振りがない。",
