      desc: "野菜の酒場。クサワケセカンドの土台にあるのは、野菜で飲める店という一貫した発想だ。居酒屋というと揚げ物や肉のつまみが主役になりがちだが、ここでは無農薬の野菜が献立の中心に据えられている。看板のひとつがベジプレートで、数種の野菜を一皿に盛り合わせ、それぞれの持ち味を引き出した前菜として供される。野菜のうまみを酒のあてに変えるという組み立ては、飲んだあとに重さを残しにくく、もう一杯、もう一品と杯を重ねやすい。アラカルトは440円ほどから用意され、少しずつ頼んで野菜の味を見比べていく楽しみがある。生のまま出すもの、火を通して甘みを引き出したものと調理を変えて出すので、同じ野菜でも表情が変わる。系列で使う野菜は、沖縄や千葉の契約農家から届く無農薬のものが軸になっていて、産地と作り手を見据えて仕入れている点も野菜居酒屋らしい。健康志向だから物足りない、ということはなく、酒の進む味付けと組み合わせの妙で満足感をつくっているのがこの店の腕どころだ。野菜を主役に据えて、ここまで飲ませる居酒屋はそう多くない。まずは数種を盛ったベジプレートから入って、その日の野菜の出来をうかがうのが、この店の楽しみ方の入口になる。",
