  lede: "国際通りの喧騒からひと筋入った牧志は、市場や路地の活気と暮らしの匂いが同居する那覇の中心だ。観光客が行き交う表通りと、地元の人が通う飲み屋や食堂が、わずかな距離で隣り合っている。沖縄モノレールの美栄橋駅から歩いて数分、その牧志の一角に牧志プリーストはある。コンクリートの外観にネオンがともる、スタイリッシュなカジュアルイタリアンだ。看板はパスタやピザで、生地から手作りするのがこの店の流儀。開くのは夕方から翌1時までと遅く、観光の一日を終えたあとや、仕事帰りの遅い時間でも迎え入れてくれる。誰かと軽く一杯やりたい夜にも、しっかり食事をしたい夜にも間口が広い。那覇の夜を、もう一軒分長く楽しみたい人に向いた店だと言っていい。",
