  lede: "大宮駅の東口を出て、繁華街の灯りをくぐりながら仲町のほうへ歩いていくと、夜が深まるほど元気になっていく一角に行き当たる。大衆酒場 げっとらは、その仲町二丁目で2023年の夏に暖簾を上げた店だ。名物に掲げるのは新鮮なレバーを使った純レバテキと、朝引きのホルモン、そして季節の野菜を巻いた串。気軽に飲める大衆酒場の構えでありながら、リノベーションされた店内は居心地よく整えられている。月曜から水曜は深夜三時まで、週末は明け方五時まで灯りをともすから、一軒目にも、終電を逃した夜の駆け込みどころにもなる。大宮で飲むなら覚えておきたい、この店の使いどころを順に見ていきたい。",
