      desc: "トム・トムが長く愛されているのは、夫婦二人で切り盛りする喫茶店ならではの距離感にある。市役所のすぐ隣という立地もあって、近隣で働く人が朝に夕に立ち寄り、自然と常連の多い店になっている。顔なじみが多い店は一見だと入りにくいと身構えがちだが、ここはスタッフの気配りが行き届いていて、初めての客にも肩肘張らない居心地を用意してくれる。毎日のように通える店というのは、味の良し悪しだけで決まるものではない。注文を覚えていてくれること、長居しても急かされないこと、いつ来ても変わらない空気があること——そうした積み重ねが、人を二度三度と呼び戻す。トム・トムにはその日常の安心感がある。西宮の生活圏にしっかり根を張った店で、近所に一軒あったらと羨ましくなる類いの喫茶だ。働く合間の十五分でも、休日のひとときでも、同じ温度で迎えてくれるのが通いたくなる理由だ。",
