  lede: "和歌山市の西の端、和歌山港にほど近い西浜に、和歌山市中央卸売市場がある。プロの仲卸が魚を競る場というと一般客には縁遠く感じるが、その総合食品センター棟「わかやままるしぇ」は二〇二〇年から市民にも開かれ、飲食店や食料品店が軒を連ねる場所になった。市場の朝の空気の中で、仕入れたばかりの魚をそのまま丼に盛る——そんな食べ方ができるのが、ここに店を構える大幸亭だ。海鮮丼や寿司を出すこの店は、観光地の海鮮処とはひと味違う、市場の現場にある一軒という顔を持っている。仲卸や買い出しの人が行き交う活気の中で、観光客も近所の人も同じ丼を囲む——その混ざり合いが、ここで食べる時間に独特の手触りを与えている。魚が運び込まれる場所で、魚を食べる。その単純で贅沢な理屈が、この店の輪郭をつくっている。和歌山は黒潮の流れ込む紀伊水道に面し、四季を通じて多彩な魚が揚がる土地でもある。その魚が集まってくる場所の只中で丼を頼むという行為そのものが、ほかの海鮮処にはない体験になっている。",
