  quote: "魚が集まる場所で、魚を食べる。大幸亭の魅力はその一点に尽きる。和歌山市中央卸売市場が市民に開いた「わかやままるしぇ」の一角で、市場仕込みの海鮮丼を気軽に味わえる一軒だ。観光の海鮮処では味わえない、現場の鮮度と市場の活気を、丼ひとつで受け取れる場所として覚えておきたい。",
